def cat = ctx.bind != null ? ctx.bind.category : null;
if (cat == null) { return; }
List category = new ArrayList();
List type = new ArrayList();
if (cat == 'queries' || cat == 'client' || cat == 'resolver' || cat == 'dnssec') {
  category.add('network'); category.add('dns'); type.add('protocol');
} else if (cat == 'lame-servers') {
  category.add('network'); category.add('dns'); type.add('info');
} else if (cat == 'xfer-in' || cat == 'xfer-out' || cat == 'notify') {
  category.add('network'); type.add('connection');
} else if (cat == 'update') {
  category.add('configuration'); type.add('change');
} else if (cat == 'security' || cat == 'unmatched') {
  category.add('network'); type.add('denied');
} else if (cat == 'config') {
  category.add('configuration'); type.add('info');
} else {
  category.add('process'); type.add('info');
}
if (ctx.event == null) { ctx.event = new HashMap(); }
ctx.event.category = category;
ctx.event.type = type;

List ips = new ArrayList();
if (ctx.client != null && ctx.client.ip != null) { ips.add(ctx.client.ip); }
if (ctx.destination != null && ctx.destination.ip != null) { ips.add(ctx.destination.ip); }
if (ctx.bind != null) {
  if (ctx.bind.resolving != null && ctx.bind.resolving.server_ip != null) { ips.add(ctx.bind.resolving.server_ip); }
  if (ctx.bind.transfer != null && ctx.bind.transfer.peer_ip != null) { ips.add(ctx.bind.transfer.peer_ip); }
  if (ctx.bind.listen != null && ctx.bind.listen.ip != null) { ips.add(ctx.bind.listen.ip); }
}
if (ips.size() > 0) {
  if (ctx.related == null) { ctx.related = new HashMap(); }
  ctx.related.ip = ips;
}

if (ctx.bind == null || ctx.bind.message == null) { return; }
String m = ctx.bind.message.toLowerCase();
String outcome = null;
if (m.contains('denied') || m.contains('refused') || m.contains('failed') || m.contains('lame server') || m.contains('unexpected rcode') || m.contains('expired') || m.contains('error') || m.contains('timeout') || m.contains('unreachable')) {
  outcome = 'failure';
} else if (m.contains('approved') || m.contains('succeeded') || m.contains('success') || m.contains('completed') || m.contains('accepted') || m.contains('loaded serial')) {
  outcome = 'success';
}
if (outcome != null) {
  if (ctx.event == null) { ctx.event = new HashMap(); }
  ctx.event.outcome = outcome;
}
